<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { RouterLink, RouterView, useRoute } from 'vue-router'
import ErrorState from '@/components/ErrorState.vue'
import { createHttpQuery } from '@/data/httpQuery'
import { fixtureQuery } from '@/data/fixtureQuery'
import { useDashboardStore } from '@/stores/dashboard'

const store = useDashboardStore()
const route = useRoute()
const pollingInterval = ref(30_000)
const apiUrl = import.meta.env.VITE_DASHBOARD_API_URL?.trim()
const lastUpdated = computed(() => store.snapshot?.observedAt)
const usingFixture = computed(() => store.snapshot?.mode === 'fixture')
store.setQueryPort(apiUrl ? createHttpQuery(apiUrl) : fixtureQuery)

onMounted(() => { void store.load() })
onBeforeUnmount(() => store.stopPolling())

function setPolling(enabled: boolean): void {
  if (enabled) store.startPolling(pollingInterval.value)
  else store.stopPolling()
}
function setPollingInterval(event: Event): void {
  const value = Number((event.target as HTMLSelectElement).value)
  if (!Number.isFinite(value) || value < 5_000) return
  pollingInterval.value = value
  if (store.polling) store.startPolling(value)
}

function formatTime(value?: string): string {
  if (!value) return '尚未更新'
  return new Intl.DateTimeFormat('zh-CN', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Shanghai' }).format(new Date(value))
}
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar">
      <RouterLink class="brand" to="/" aria-label="SciWeave 看板首页"><span class="brand__mark" aria-hidden="true"><i></i><i></i><i></i></span><span><strong>SciWeave</strong><small>RESEARCH OS</small></span></RouterLink>
      <div class="sidebar__section"><p>工作空间</p><span class="workspace-switch"><span class="workspace-switch__dot"></span>研究协作空间 <span aria-hidden="true">⌄</span></span></div>
      <nav class="primary-nav" aria-label="主导航">
        <p>观察视图</p>
        <RouterLink to="/" exact-active-class="nav-active"><span class="nav-icon" aria-hidden="true">◫</span>项目总览<span class="nav-arrow" aria-hidden="true">↗</span></RouterLink>
        <RouterLink to="/route" active-class="nav-active"><span class="nav-icon" aria-hidden="true">⌘</span>研究路线<span class="nav-count">{{ store.snapshot?.tasks.length ?? '—' }}</span></RouterLink>
        <RouterLink to="/knowledge" active-class="nav-active"><span class="nav-icon" aria-hidden="true">▤</span>知识与候选<span class="nav-count">{{ store.snapshot?.wikiCandidates?.length ?? '—' }}</span></RouterLink>
        <RouterLink to="/operations" active-class="nav-active"><span class="nav-icon" aria-hidden="true">◉</span>运行观察<span v-if="store.snapshot?.partial" class="nav-alert" aria-label="包含部分数据"></span></RouterLink>
      </nav>
      <div class="sidebar__bottom"><div class="read-only-card"><span class="read-only-card__icon" aria-hidden="true">◌</span><div><strong>安全观察模式</strong><small>此看板不会修改领域数据</small></div></div><div class="user-chip"><span class="user-avatar">S</span><span><strong>研究协作者</strong><small>只读访问</small></span><span class="user-menu" aria-hidden="true">···</span></div></div>
    </aside>

    <main class="main-column"><header class="topbar"><div class="topbar__crumb"><span>SCIWEAVE</span><span aria-hidden="true">/</span><strong>{{ route.path === '/' ? '概览' : route.path.startsWith('/tasks/') ? '任务详情' : route.path === '/route' ? '研究路线' : route.path === '/knowledge' ? '知识与候选' : '运行观察' }}</strong></div><div class="topbar__actions"><span class="snapshot-time"><span class="live-dot" :class="{ 'live-dot--stale': store.state === 'error' }"></span>{{ store.state === 'loading' ? '同步中' : `快照 ${formatTime(lastUpdated)}` }}</span><label class="poll-switch"><input v-model="store.polling" type="checkbox" aria-label="自动刷新" @change="setPolling(store.polling)" /><span>自动刷新</span></label><select v-if="store.polling" class="poll-interval" aria-label="自动刷新间隔" :value="pollingInterval" @change="setPollingInterval"><option :value="30_000">30 秒</option><option :value="60_000">1 分钟</option><option :value="300_000">5 分钟</option></select><button class="refresh-button" type="button" :disabled="store.state === 'loading' || store.refreshing" aria-label="刷新看板数据" @click="store.refresh()"><span :class="{ spinning: store.refreshing }" aria-hidden="true">↻</span><span>{{ store.refreshing ? '刷新中' : '刷新' }}</span></button></div></header>
      <div class="main-content"><ErrorState v-if="store.state === 'error'" :message="store.errorMessage" :busy="store.refreshing" @retry="store.refresh" /><div v-if="usingFixture" class="fixture-banner" role="status"><span aria-hidden="true">◌</span><div><strong>演示数据模式</strong><p>当前展示的是本地 fixture，不代表真实服务状态。配置只读快照 API 后可切换到实时来源。</p></div><RouterLink to="/operations">查看接入状态 <span aria-hidden="true">↗</span></RouterLink></div><div v-if="store.state === 'empty'" class="empty-snapshot" role="status"><span aria-hidden="true">○</span><div><strong>目前没有研究记录</strong><p>已读取的数据来源没有项目或活动记录；这与来源不可用不同。</p></div></div><div v-if="store.state === 'loading' && !store.snapshot" class="loading-card" role="status"><span class="loading-card__spinner" aria-hidden="true"></span><strong>正在整理研究快照</strong><p>汇总当前可读取的路线、执行和服务状态。</p></div><RouterView v-else-if="store.snapshot" /><div v-else-if="store.state === 'empty'" class="loading-card"><strong>当前没有可展示的数据</strong><p>数据服务可用，但尚未返回项目或任务记录。</p></div></div>
      <footer class="global-footer"><span>SCIWEAVE · 研究进展观察</span><span>状态来自各领域已确认的查询结果</span></footer>
    </main>
  </div>
</template>

